'use strict';function createState(i={}){let s=Object.assign({},i),l={},h=[];return{get(k){return s[k]},set(k,v){h.push({key:k,prev:s[k],next:v});s[k]=v;if(l[k])l[k].forEach(f=>f(v))},subscribe(k,f){if(!l[k])l[k]=[];l[k].push(f)},undo(){const e=h.pop();if(e)s[e.key]=e.prev},snapshot(){return Object.assign({},s)}}}module.exports={createState};
